const P2=(e)=>{const r=phone.getBoundingClientRect(),k=393/r.width;return[(e.clientX-r.left)*k,(e.clientY-r.top)*k]};
let sx=0,sy=0;
phone.addEventListener('pointerdown',e=>{sx=e.clientX;sy=e.clientY;const b=e.target.closest('[data-go],[data-act],[data-back],.chip');if(b&&!b.closest('.sheet')&&b.getAttribute('data-act')!=='bar'){b.animate([{transform:getComputedStyle(b).transform==='none'?'scale(1)':getComputedStyle(b).transform},{transform:'scale(.93)'}],{duration:110,easing:'ease-out',fill:'forwards'});const up=()=>{b.getAnimations().forEach(x=>x.cancel());b.animate([{transform:'scale(.93)'},{transform:'scale(1.04)'},{transform:'scale(1)'}],{duration:380,easing:E});removeEventListener('pointerup',up)};addEventListener('pointerup',up)}});
phone.addEventListener('pointerup',e=>{if(busy||!cur.el)return;const dx=e.clientX-sx,dy=e.clientY-sy,s=S[cur.id];
  if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5&&s.swipe){const t=dx<0?s.swipe.l:s.swipe.r;if(t){vib(8);go(t,dx<0?'slide':'back');return}}
  if(Math.abs(dx)>10||Math.abs(dy)>10)return;const[x,y]=P2(e);
  const r=document.createElement('div');r.className='rip';r.style.left=x+'px';r.style.top=y+'px';phone.appendChild(r);setTimeout(()=>r.remove(),520);
  const b=e.target.closest('[data-go],[data-act],[data-back]');if(!b)return;b._x=x;b._y=y;vib(8);
  if(b.hasAttribute('data-back')){go(BACK[cur.id]||'home','back');return}
  if(b.dataset.act){const f=s.act&&s.act[b.dataset.act];f&&f(b);return}
  if(b.classList.contains('fab')){const sv=$('svg:last-child',b)||b;b.animate([{transform:'rotate(0)'},{transform:'rotate(90deg) scale(1.15)'}],{duration:450,easing:E})}
  if(b.dataset.go){if(b.dataset.tr==='row'){const[a1,a2]=b.dataset.row.split(',').map(Number);go(b.dataset.go,'row',[a1,a2]);return}go(b.dataset.go,b.dataset.tr||'push',x,y)}});
/* ubicación real: si diste permiso, la app sabe si estás dentro del parque */
const PARQUE=[-34.6067,-58.4356];
function chequeo(){if(!ST.ubic||!navigator.geolocation)return;navigator.geolocation.getCurrentPosition(p=>{const d=Math.hypot((p.coords.latitude-PARQUE[0])*111000,(p.coords.longitude-PARQUE[1])*92000);const n=d<380;if(n!==ST.dentro){ST.dentro=n;if(cur.id==='home'||cur.id==='menu')go(cur.id,'fade')}},()=>{},{timeout:8000,maximumAge:60000})}
setInterval(chequeo,60000);setTimeout(chequeo,1500);
